def img_url(photo_id: str) -> str:
    return f"https://images.unsplash.com/photo-{photo_id}?w=600&q=80"


def card_html(
    studio: str,
    name: str,
    typ: str,
    price: str,
    photo_id: str,
    tier_cls: str,
    tier_label: str,
    width_cls: str,
    width_label: str,
) -> str:
    alt = f"{name} — {typ}"
    return f"""          <li>
            <article class="product-card">
              <div class="product-card__badges">
                <span class="shelf-badge shelf-badge--{tier_cls}">{tier_label}</span>
                <span class="shelf-badge shelf-badge--{width_cls}">{width_label}</span>
              </div>
              <p class="product-card__studio">{studio}</p>
              <div class="product-card__image"><img src="{img_url(photo_id)}" alt="{alt}" width="600" height="600" loading="lazy" /></div>
              <div class="product-card__body">
                <h3 class="product-card__name">{name}</h3>
                <p class="product-card__type">{typ}</p>
                <p class="product-card__price">{price} ₽</p>
              </div>
            </article>
          </li>"""


def zone_lists(room_matrix: list) -> tuple[str, str, str]:
    top, mid, low = [], [], []
    for di, studio in enumerate(DESIGNERS):
        for j, (name, typ, price, pid) in enumerate(room_matrix[di]):
            _, t_cls, t_lbl, w_cls, w_lbl = TIER_CFG[j]
            block = card_html(studio, name, typ, price, pid, t_cls, t_lbl, w_cls, w_lbl)
            if t_cls == "tier-top":
                top.append(block)
            elif t_cls == "tier-mid":
                mid.append(block)
            else:
                low.append(block)
    return "\n".join(top), "\n".join(mid), "\n".join(low)


def replace_ul_after_anchor(text: str, anchor: str, new_inner: str) -> str:
    pos = text.find(anchor)
    if pos < 0:
        raise ValueError(f"anchor not found: {anchor}")
    ul_pos = text.find("<ul", pos)
    if ul_pos < 0:
        raise ValueError(f"<ul after {anchor}")
    gt = text.find(">", ul_pos)
    open_tag = text[ul_pos : gt + 1]
    close_pos = text.find("</ul>", gt)
    return text[:ul_pos] + open_tag + "\n" + new_inner + "\n        </ul>" + text[close_pos + len("</ul>") :]


def patch_room(path: pathlib.Path, room_matrix: list) -> None:
    text = path.read_text(encoding="utf-8")
    top, mid, low = zone_lists(room_matrix)
    text = replace_ul_after_anchor(text, 'id="zone-top"', top)
    text = replace_ul_after_anchor(text, 'id="zone-mid"', mid)
    text = replace_ul_after_anchor(text, 'id="zone-low"', low)
    path.write_text(text, encoding="utf-8")


def main() -> None:
    root = pathlib.Path(__file__).resolve().parents[1]
    patch_room(root / "room-lighting.html", LIGHTING)
    patch_room(root / "room-texture.html", TEXTURE)
    patch_room(root / "room-decor.html", DECOR)
    patch_room(root / "room-furniture.html", FURNITURE)
    print("Patched room-*.html")


if __name__ == "__main__":
    main()
